std::unique_ptr<T> // Exclusive ownership. RAII guarantees delete.

// Construction (C++14+)
std::unique_ptr<int> up1 = std::make_unique<int>(42);

// Cannot copy, must move ownership
std::unique_ptr<int> up2 = std::move(up1);
// up1 is now nullptr

// Access
int val = *up2;
up2->method();

// Custom Deleter (type required in declaration)
struct FileCloser { void operator()(FILE* f) const { fclose(f); } };
std::unique_ptr<FILE, FileCloser> log_file(fopen("log", "w"));
// log_file automatically closes on scope exit.
// ----------------------------------------------------------------------

std::shared_ptr<T> // Shared ownership via reference count.

// Construction (prefer make_shared for efficiency)
std::shared_ptr<Resource> sp1 = 
    std::make_shared<Resource>(5);

// Copy shares ownership (count = 2)
std::shared_ptr<Resource> sp2 = sp1;

// Reference count access
size_t users = sp1.use_count(); // 2

// Access raw pointer (use only if necessary)
Resource* raw = sp1.get();

// Resetting releases ownership (decrements count)
sp1.reset(); 
// Resource is destroyed when users == 0.
// ----------------------------------------------------------------------

std::weak_ptr<T> // Non-owning observation pointer.

std::shared_ptr<Node> strong = std::make_shared<Node>();
std::weak_ptr<Node> observer = strong; // Observe strong

// Cannot access directly. Must check and 'lock'.
if (std::shared_ptr<Node> temp = observer.lock()) {
    // Object is guaranteed to exist inside this scope
    temp->operation();
} else {
    // Object has been destroyed
}

// Check if the managed object is destroyed
bool gone = observer.expired();
// Used to break cyclic dependencies (A holds B, B holds A).
